def decode_runs(text):
    if not text:
        return ""
    result = []
    i = 0
    n = len(text)
    while i < n:
        # Expect a digit to start a run
        if not text[i].isdigit():
            raise ValueError("Missing count")
        count_str = ''
        while i < n and text[i].isdigit():
            count_str += text[i]
            i += 1
        # After digits, we must have a letter
        if i >= n:
            raise ValueError("Trailing numbers")
        if not ('a' <= text[i] <= 'z'):
            raise ValueError("Invalid character")
        letter = text[i]
        i += 1
        count = int(count_str)
        if count <= 0:
            raise ValueError("Zero count")
        result.append(letter * count)
    return ''.join(result)

def flatten(value):
    """
    Recursively flatten lists and tuples into a new list.
    All other values, including strings and dictionaries, are treated as atomic.
    """
    if isinstance(value, (list, tuple)):
        result = []
        for item in value:
            result.extend(flatten(item))
        return result
    else:
        return [value]

import copy
def deep_merge(left, right):
    """
    Recursively merge two dictionaries without mutating either input.
    Values from right replace values from left unless both are dictionaries,
    in which case they are merged recursively.
    Returns a new dictionary with independent copies of nested values.
    """
    if isinstance(left, dict) and isinstance(right, dict):
        # Start with a deep copy of left to avoid mutating the original
        merged = copy.deepcopy(left)
        for key, val in right.items():
            if key in merged and isinstance(merged[key], dict) and isinstance(val, dict):
                # Both sides are dictionaries: merge recursively
                merged[key] = deep_merge(merged[key], val)
            else:
                # Otherwise, right's value takes precedence (deep copied)
                merged[key] = copy.deepcopy(val)
        return merged
    else:
        # If either side is not a dictionary, right's value wins (deep copied)
        return copy.deepcopy(right) if right is not None else copy.deepcopy(left)

def json_pointer(value, pointer):
    """
    Resolve a JSON Pointer (RFC6901) into a value within a Python object.
    Supports dictionaries and lists.
    Raises ValueError for malformed pointers, missing paths, or invalid list indices.
    """
    if pointer == "":
        return value

    # Step 1: decode '~0' and '~1' escapes in the pointer string
    decoded_parts = []
    i = 0
    n = len(pointer)
    while i < n:
        c = pointer[i]
        if c == '~':
            if i + 1 >= n:
                raise ValueError("Malformed escape: '~' at end of pointer")
            next_c = pointer[i + 1]
            if next_c == '0':
                decoded_parts.append('~')
                i += 2
            elif next_c == '1':
                decoded_parts.append('/')
                i += 2
            else:
                raise ValueError(f"Malformed escape: '~{next_c}' in pointer")
        else:
            decoded_parts.append(c)
            i += 1
    ptr = ''.join(decoded_parts)

    # Step 2: split the decoded pointer into tokens
    if ptr.startswith('/'):
        tokens = ptr.split('/')[1:]  # ignore empty first element
    else:
        tokens = ptr.split('/')

    current = value
    for token in tokens:
        if isinstance(current, dict):
            if token in current:
                current = current[token]
            else:
                raise ValueError(f"Path '{token}' not found")
        elif isinstance(current, list):
            # token must be a canonical decimal integer
            if not token.isdigit():
                raise ValueError(f"List index must be numeric: {token}")
            if len(token) > 1 and token[0] == '0':
                raise ValueError(f"List index must be canonical: {token}")
            idx = int(token)
            if idx < 0 or idx >= len(current):
                raise ValueError(f"List index out of range: {idx}")
            current = current[idx]
        else:
            raise ValueError(f"Path '{token}' not found")
    return current

def tokenize(s):
    """Convert input string into a list of tokens."""
    tokens = []
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c.isspace():
            i += 1
            continue
        if c.isdigit():
            start = i
            while i < n and s[i].isdigit():
                i += 1
            num = int(s[start:i])
            tokens.append(('NUMBER', num))
            continue
        if c == '+':
            tokens.append(('PLUS', '+'))
        elif c == '-':
            tokens.append(('MINUS', '-'))
        elif c == '*':
            tokens.append(('MULTIPLY', '*'))
        elif c == '(':
            tokens.append(('LPAREN', '('))
        elif c == ')':
            tokens.append(('RPAREN', ')'))
        else:
            raise ValueError(f"Invalid character: {c}")
        i += 1
    return tokens
class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def current(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def eat(self, token_type):
        cur = self.current()
        if cur and cur[0] == token_type:
            self.pos += 1
            return cur
        else:
            raise ValueError(f"Expected {token_type}, got {cur}")

    def parse_expression(self):
        """Parse addition and subtraction."""
        value = self.parse_term()
        while True:
            cur = self.current()
            if cur and cur[0] == 'PLUS':
                self.eat('PLUS')
                right = self.parse_term()
                value += right
            elif cur and cur[0] == 'MINUS':
                self.eat('MINUS')
                right = self.parse_term()
                value -= right
            else:
                break
        return value

    def parse_term(self):
        """Parse multiplication."""
        value = self.parse_factor()
        while True:
            cur = self.current()
            if cur and cur[0] == 'MULTIPLY':
                self.eat('MULTIPLY')
                right = self.parse_factor()
                value *= right
            else:
                break
        return value

    def parse_factor(self):
        """Parse unary plus/minus, numbers, or parentheses."""
        sign = 1
        cur = self.current()
        while cur and cur[0] in ('PLUS', 'MINUS'):
            if cur[0] == 'MINUS':
                sign *= -1
            # PLUS leaves sign unchanged
            self.eat(cur[0])
            cur = self.current()

        cur = self.current()
        if cur and cur[0] == 'NUMBER':
            self.eat('NUMBER')
            value = cur[1]
        elif cur and cur[0] == 'LPAREN':
            self.eat('LPAREN')
            value = self.parse_expression()
            self.eat('RPAREN')
        else:
            raise ValueError(f"Expected number or '(', got {cur}")
        return value * sign
def expression(text):
    """Evaluate the arithmetic expression given as a string."""
    tokens = tokenize(text)
    parser = Parser(tokens)
    result = parser.parse_expression()
    if parser.current() is not None:
        raise ValueError("Invalid syntax")
    return result

from functools import lru_cache
def glob_match(pattern: str, text: str) -> bool:
    """Return True if pattern matches entire text using wildcards ? and *."""
    @lru_cache(maxsize=None)
    def dp(p_idx: int, t_idx: int) -> bool:
        # If pattern exhausted, text must also be exhausted
        if p_idx == len(pattern):
            return t_idx == len(text)
        # If text exhausted, remaining pattern must be all '*'
        if t_idx == len(text):
            return all(pattern[i] == '*' for i in range(p_idx, len(pattern)))

        p = pattern[p_idx]
        if p == '*':
            # '*' can match zero characters (skip it) or one more character (consume text)
            return dp(p_idx + 1, t_idx) or dp(p_idx, t_idx + 1)
        elif p == '?' or p == text[t_idx]:
            # '?' matches any single character, or literal match
            return dp(p_idx + 1, t_idx + 1)
        else:
            # No match
            return False

    return dp(0, 0)

def memo_cycle(definitions, name):
    """
    Compute the value of `name` given a definitions dictionary.
    definitions: dict mapping name -> int or list of dependency names.
    The value of a name defined as a list is the sum of the values of its dependencies.
    Shared dependencies are counted each time they appear.
    Raises ValueError on any reachable cycle or missing dependency.
    """
    memo = {}
    visiting = set()

    def resolve(n):
        if n in memo:
            return memo[n]
        if n in visiting:
            raise ValueError(f"Cycle detected involving {n}")
        if n not in definitions:
            raise ValueError(f"Missing dependency: {n}")
        visiting.add(n)
        try:
            val = definitions[n]
            if isinstance(val, int):
                result = val
            else:  # list
                result = 0
                for dep in val:
                    dep_val = resolve(dep)
                    result += dep_val
            memo[n] = result
            return result
        finally:
            visiting.remove(n)

    return resolve(name)
